      <TouchableOpacity
        testID="back-button"
        onPress={() => navigation.goBack()}
        style={styles.backButton}
      >
        <Text style={styles.backButtonText}>‹ Back</Text>
      </TouchableOpacity>

      <Text testID="screen-title" style={styles.title}>
        Notifications
      </Text>

